// Consola de regulación 279 dentro del centro de control (pcc-centro277): trenes y regímenes de marcha,
// señalización (CBTC en Línea 1, bloque fijo en Línea 8), restricciones temporales de velocidad,
// regulación del intervalo, alarmas con registrador de eventos y Agenda 2030.
import {MODES279,SIGNALLING279,ASSUMED279,SOURCES279R,blocks279,occupiedBlocks279,clock279} from './regulacion279.js?v=279';
import {ODS279,FESEN279,STC2030,indicators279} from './agenda2030-279.js?v=279';
import {brakeInfo279,SOURCES279} from './braking279.js?v=279';

const TABS=[['trenes','Trenes y regímenes'],['senales','Señalización'],['regulacion','Restricciones y regulación'],['alarmas','Alarmas y registro'],['agenda','Agenda 2030']];
const fmt=(n,d=0)=>n==null||!isFinite(n)?'—':Number(n).toLocaleString('es-MX',{maximumFractionDigits:d,minimumFractionDigits:d});
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const MODE_COLORS={PA:'#79dbc1',CMC:'#ffd38a',CML:'#ff9f5e'};

export function mountConsole279(host,{engine,regulator,panels=[],onFleet,onSpeed,speed=1,doc=host.ownerDocument}){
 const lines=regulator.lines,root=doc.createElement('section');root.className='reg279';root.setAttribute('aria-label','Consola de regulación');
 root.innerHTML=`<header class="reg279-head"><div><small>CONSOLA DE REGULACIÓN</small><h3>Trenes, señales, restricciones y energía</h3></div>
 <div class="reg279-run"><label>Trenes por línea <select data-reg-fleet>${[4,6,8,10].map(n=>`<option value="${n}"${n===engine.fleet?' selected':''}>${n}</option>`).join('')}</select></label><label>Velocidad de la simulación <select data-reg-speed>${[[1,'×1 tiempo real'],[5,'×5'],[10,'×10']].map(([v,t])=>`<option value="${v}"${v===speed?' selected':''}>${t}</option>`).join('')}</select></label><output data-reg-clock></output></div></header>
 <div class="reg279-tabs" role="tablist">${TABS.map(([id,t],i)=>`<button type="button" role="tab" data-reg-tab="${id}" aria-selected="${i===0}">${t}</button>`).join('')}</div>
 <div class="reg279-body" data-reg-body></div>
 <p class="reg279-note">${ASSUMED279.note}</p>
 <p class="reg279-note">Fuentes: ${SOURCES279R.map(s=>s.url?`<a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)}</a>`:esc(s.title)).join(' · ')} · <a href="${SOURCES279.alamys.url}" target="_blank" rel="noopener">${esc(SOURCES279.alamys.title)}</a>.</p>`;
 host.append(root);const q=s=>root.querySelector(s),body=q('[data-reg-body]');let tab='trenes',busy=false,lastRender=0,flash='';
 // No volver a dibujar mientras el usuario tiene el botón presionado: así no se pierde el clic.
 root.addEventListener('pointerdown',()=>{busy=true;});for(const ev of['pointerup','pointercancel','pointerleave'])root.addEventListener(ev,()=>{setTimeout(()=>{busy=false;},60);});
 root.addEventListener('focusin',e=>{if(e.target.matches?.('select,input'))busy=true;});root.addEventListener('focusout',e=>{if(e.target.matches?.('select,input'))busy=false;});
 const say=(r,ok)=>{flash=r.ok===false?r.why:ok||'';render(true);};
 root.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b)return;const d=b.dataset;
  if(d.regTab){tab=d.regTab;for(const x of root.querySelectorAll('[data-reg-tab]'))x.setAttribute('aria-selected',String(x.dataset.regTab===tab));flash='';render(true);return;}
  if(d.regMode)return say(regulator.setMode(d.regTrain,d.regMode),`${d.regTrain}: régimen ${d.regMode}`);
  if(d.regOver)return say(regulator.overspeed(d.regOver),`${d.regOver}: ejercicio de sobrevelocidad en curso`);
  if(d.regDead)return say(regulator.deadman(d.regDead),`${d.regDead}: manipulador soltado`);
  if(d.regRearm)return say(regulator.rearm(d.regRearm),`${d.regRearm}: ATP rearmado`);
  if(d.regLtvDel){regulator.removeLtv(d.regLtvDel);render(true);return;}
  if(d.regLtvAdd!=null){const l=+q('[data-reg-ltv-line]').value,a=+q('[data-reg-ltv-from]').value,b2=+q('[data-reg-ltv-to]').value,v=+q('[data-reg-ltv-kmh]').value;const r=regulator.addLtv(l,a,b2,v);flash=r?`Restricción de ${v} km/h aplicada`:'Elige dos estaciones distintas';busy=false;render(true);return;}
  if(d.regRegToggle){const l=+d.regRegToggle,R=regulator.reg[l],v=+q(`[data-reg-target="${l}"]`)?.value||R.target;regulator.setRegulation(l,!R.on,v);busy=false;render(true);return;}
  if(d.regFilter){filter=d.regFilter;render(true);return;}});
 root.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-reg-fleet]')){onFleet?.(+el.value);busy=false;render(true);}else if(el.matches('[data-reg-speed]')){onSpeed?.(+el.value);busy=false;}else if(el.matches('[data-reg-ltv-line]')){ltvLine=+el.value;busy=false;render(true);}else if(el.matches('[data-reg-target]')){const l=+el.dataset.regTarget;regulator.setRegulation(l,regulator.reg[l].on,+el.value);busy=false;}});
 let filter='all',ltvLine=lines[0];

 function trains(){return lines.map(l=>{const rows=regulator.rows(l),sig=SIGNALLING279[l];return `<h4 class="reg279-line l${l}">Línea ${l} · ${esc(sig.name)}</h4><div class="reg279-scroll"><table class="reg279-table"><tr><th>Tren</th><th>Régimen</th><th>km/h · permitido</th><th>Limita</th><th>${sig.kind==='cbtc'?'Autoridad CBTC':'Hasta la señal en rojo'}</th><th>Tren de adelante</th><th>Freno eléctrico</th><th>Estado</th><th>Ejercicios</th></tr>${rows.map(r=>{const b=brakeInfo279(r.model),tr=r.atp?.braking;return `<tr class="${tr?'trip':''}"><td><b>${r.id}</b><small>${esc(r.model)} · ${r.dir>0?'▶':'◀'}</small></td><td><div class="reg279-seg">${Object.keys(MODES279).map(m=>`<button type="button" data-reg-mode="${m}" data-reg-train="${r.id}" aria-pressed="${r.mode===m}" title="${esc(MODES279[m].name)}" style="--m:${MODE_COLORS[m]}">${m}</button>`).join('')}</div></td><td><b>${fmt(r.speed)}</b> / ${fmt(r.limit)}</td><td>${esc(r.limitBy)}</td><td>${r.auth?.dist==null?'Vía libre':fmt(r.auth.dist)+' m'}</td><td>${r.ahead?`${r.ahead.id} · ${fmt(r.ahead.gap)} m`:'—'}</td><td class="${b.type==='rheo'?'rheo':'regen'}">${esc(b.short)}</td><td>${esc(r.state)}${r.inStation&&r.station?` · ${esc(r.station)}`:''}</td><td class="reg279-acts">${tr?`<button type="button" data-reg-rearm="${r.id}">Rearmar ATP</button>`:`<button type="button" data-reg-over="${r.id}" ${r.mode==='PA'?'disabled':''}>Exceso de velocidad</button><button type="button" data-reg-dead="${r.id}" ${r.mode==='PA'?'disabled':''}>Soltar hombre muerto</button>`}</td></tr>`;}).join('')}</table></div>`;}).join('')+`<div class="reg279-cards">${Object.entries(MODES279).map(([k,m])=>`<article style="--m:${MODE_COLORS[k]}"><b>${k} · ${esc(m.name)}</b><p>${esc(m.text)}</p></article>`).join('')}</div><p class="reg279-hint">El régimen solo cambia con el tren detenido. Los ejercicios funcionan en CMC y CML: el ATP o el hombre muerto frenan el tren y queda detenido hasta que lo rearmas desde aquí.</p>`;}

 function tco(l){const line=engine.lines[l],sig=SIGNALLING279[l],W=1000,X=x=>40+x/line.total*(W-80),yT={1:58,[-1]:118};let h=`<rect x="0" y="0" width="${W}" height="180" style="fill:#0a1418"/>`;
  for(const r of regulator.ltv.filter(r=>r.line===l))h+=`<rect x="${X(r.from)}" y="36" width="${Math.max(2,X(r.to)-X(r.from))}" height="104" style="fill:#e8d44d22;stroke:#e8d44d;stroke-dasharray:4 3"/><text x="${(X(r.from)+X(r.to))/2}" y="32" text-anchor="middle" style="fill:#e8d44d;font-size:10px">${r.kmh} km/h</text>`;
  for(const dir of[1,-1]){const y=yT[dir],tr=engine.trains.filter(t=>t.line===l);
   if(sig.kind==='fixed'){const B=regulator.blockCache.get(l)||blocks279(line),occ=occupiedBlocks279(B,tr,dir);for(let k=0;k<B.length-1;k++){const o=occ.has(k),next=occ.has(k+dir),c=o?'#ff4d3d':next?'#ffd34d':'#3fd17f';h+=`<line x1="${X(B[k])+1}" x2="${X(B[k+1])-1}" y1="${y}" y2="${y}" style="stroke:${c};stroke-width:5;opacity:${o?1:.75}"/>`;const sx=X(dir>0?B[k]:B[k+1]);h+=`<circle cx="${sx}" cy="${y+(dir>0?-9:9)}" r="3" style="fill:${o?'#ff4d3d':next?'#ffd34d':'#3fd17f'}"><title>Señal de entrada al cantón ${k+1}: ${o?'rojo':next?'amarillo':'verde'}</title></circle>`;}}
   else{h+=`<line x1="${X(0)}" x2="${X(line.total)}" y1="${y}" y2="${y}" style="stroke:#5b7f8a;stroke-width:5"/>`;for(const t of tr){if((t.direction||1)!==dir)continue;const a=regulator.authority(t);if(a?.end!=null)h+=`<line x1="${X(t.position)}" x2="${X(a.end)}" y1="${y}" y2="${y}" style="stroke:#39a7ff;stroke-width:5;opacity:.85"><title>Autoridad de movimiento de ${t.id}: ${fmt(a.dist)} m</title></line>`;}}
   h+=`<text x="10" y="${y+4}" style="fill:#93a39d;font-size:10px">${dir>0?'V1':'V2'}</text>`;
   for(const t of tr){if((t.direction||1)!==dir)continue;const m=regulator.mode(t),trip=regulator.atp.get(t.id)?.braking,x1=X(t.position),x0=X(t.position-dir*ASSUMED279.trainLength);h+=`<g><title>${t.id} · ${m} · ${fmt(t.speed*3.6)} km/h${trip?' · freno de urgencia':''}</title><rect x="${Math.min(x0,x1)}" y="${y-6}" width="${Math.max(6,Math.abs(x1-x0))}" height="12" rx="3" style="fill:${trip?'#ff4d3d':MODE_COLORS[m]};stroke:#0a1418"/><text x="${x1+(dir>0?4:-4)}" y="${y+(dir>0?-11:20)}" text-anchor="${dir>0?'start':'end'}" style="fill:#f2f6f4;font-size:10px;font-weight:700">${t.id.slice(-2)} ${m}</text></g>`;}}
  line.stations.forEach((s,i)=>{const x=X(line.distances[i]);h+=`<line x1="${x}" x2="${x}" y1="48" y2="128" style="stroke:#ffffff26"/><text x="${x}" y="150" text-anchor="end" transform="rotate(-35 ${x} 150)" style="fill:#c9d8d4;font-size:9px">${esc(s.nombre)}</text>`;});
  return `<h4 class="reg279-line l${l}">Línea ${l} · ${esc(sig.name)}</h4><p class="reg279-hint">${esc(sig.text)}</p><svg viewBox="0 0 ${W} 180" class="reg279-tco" role="img" aria-label="Tablero de la Línea ${l}">${h}</svg>`;}
 function signals(){return lines.map(tco).join('')+`<div class="reg279-legend"><span style="--c:#3fd17f">Cantón libre · señal verde</span><span style="--c:#ffd34d">Cantón libre con el siguiente ocupado · amarillo</span><span style="--c:#ff4d3d">Cantón ocupado · rojo</span><span style="--c:#39a7ff">Autoridad de movimiento CBTC</span><span style="--c:#e8d44d">Restricción temporal</span></div><p class="reg279-hint">En bloque fijo el tren se detiene ante la señal del primer cantón ocupado. En CBTC la autoridad llega hasta la cola del tren de adelante menos ${ASSUMED279.cbtcMargin} m.</p>`;}

 function regulation(){const L=engine.lines[ltvLine],opts=L.stations.map((s,i)=>`<option value="${i}">${esc(s.nombre)}</option>`).join('');
  return `<h4>Restricción temporal de velocidad</h4><p class="reg279-hint">Por obra en la vía, falla de equipo o un andén con mucha gente, el P.C.C. limita la velocidad en un tramo. Los trenes frenan antes de entrar para llegar ya con la velocidad permitida.</p>
  <div class="reg279-form"><label>Línea <select data-reg-ltv-line>${lines.map(l=>`<option value="${l}"${l===ltvLine?' selected':''}>Línea ${l}</option>`).join('')}</select></label><label>Desde <select data-reg-ltv-from>${opts}</select></label><label>Hasta <select data-reg-ltv-to>${L.stations.map((s,i)=>`<option value="${i}"${i===2?' selected':''}>${esc(s.nombre)}</option>`).join('')}</select></label><label>km/h <input type="number" min="5" max="60" step="5" value="25" data-reg-ltv-kmh></label><button type="button" data-reg-ltv-add>Aplicar restricción</button></div>
  <ul class="reg279-list">${regulator.ltv.length?regulator.ltv.map(r=>`<li><b>Línea ${r.line} · ${r.kmh} km/h</b> ${esc(r.label)} <button type="button" data-reg-ltv-del="${r.id}">Levantar</button></li>`).join(''):'<li>Sin restricciones activas.</li>'}</ul>
  <h4>Regulación del intervalo</h4><p class="reg279-hint">Si un tren va a salir demasiado pronto detrás del anterior, la regulación lo retiene en la estación hasta acercarse al intervalo objetivo (máximo ${ASSUMED279.maxRegulationHold} s por parada). Así no se forman trenes pegados y huecos largos.</p>
  <table class="reg279-table"><tr><th>Línea</th><th>Intervalo objetivo</th><th>Intervalo real · vía 1</th><th>Intervalo real · vía 2</th><th>Regulación</th></tr>${lines.map(l=>{const R=regulator.reg[l],a=regulator.interval(l,1),b=regulator.interval(l,-1),ok=v=>v==null?'':Math.abs(v-R.target)<R.target*.2?'ok':'warn';return `<tr><td>Línea ${l}</td><td><input type="number" min="60" max="900" step="15" value="${R.target}" data-reg-target="${l}"> s</td><td class="${ok(a)}">${a==null?'Midiendo…':fmt(a)+' s'}</td><td class="${ok(b)}">${b==null?'Midiendo…':fmt(b)+' s'}</td><td><button type="button" data-reg-reg-toggle="${l}" aria-pressed="${R.on}">${R.on?'Activa':'Apagada'}</button></td></tr>`;}).join('')}</table>
  <p class="reg279-hint">Con más trenes por línea el intervalo baja y aparecen las señales en amarillo y rojo. La regulación y las restricciones solo existen en este centro de práctica: el simulador principal no cambia.</p>`;}

 function alarms(){const list=regulator.events.filter(e=>filter==='all'||e.level===filter||filter==='alarm'&&e.level==='critical'),count=l=>regulator.events.filter(e=>e.level===l).length;
  return `<div class="reg279-counts"><button type="button" data-reg-filter="all" aria-pressed="${filter==='all'}">Todo · ${regulator.events.length}</button><button type="button" data-reg-filter="alarm" aria-pressed="${filter==='alarm'}">Alarmas · ${count('alarm')+count('critical')}</button><button type="button" data-reg-filter="critical" aria-pressed="${filter==='critical'}">Críticas · ${count('critical')}</button></div>
  <div class="reg279-scroll tall"><table class="reg279-table log"><tr><th>Hora</th><th>Línea</th><th>Tren</th><th>Evento</th></tr>${list.slice(0,80).map(e=>`<tr class="${e.level}"><td>${e.time}</td><td>${e.line??'—'}</td><td>${e.train??'—'}</td><td>${esc(e.text)}</td></tr>`).join('')||'<tr><td colspan="4">Sin eventos.</td></tr>'}</table></div>
  <p class="reg279-hint">Como el registrador de eventos de la presentación (diapositiva 57): cada cambio de régimen, intervención del ATP, hombre muerto, rearme, corte de tensión, restricción y retención queda con hora y tren.</p>`;}

 function agenda(){const energies=panels.map(p=>p.energy279).filter(Boolean),I=indicators279(energies,{boarded:engine.boarded});const rows=panels.map((p,i)=>{const e=p.energy279;return e?`<tr><td>Línea ${lines[i]}</td><td>${fmt(e.drawKWh,1)}</td><td>${fmt(e.regenKWh,1)}</td><td class="rheo">${fmt(e.rheoKWh,1)}</td></tr>`:'';}).join('');
  const val={regen:`<b>${fmt(I.regenKWh,1)} kWh</b> regresaron a la barra guía (${fmt(I.brakeReuse*100)} % de lo frenado)`,resilience:(()=>{const c=regulator.events.filter(e=>e.level==='critical').length,r=regulator.ltv.length;return `<b>${c}</b> ${c===1?'evento crítico atendido':'eventos críticos atendidos'} · ${r} ${r===1?'restricción activa':'restricciones activas'}`;})(),passengers:`<b>${fmt(I.passengers)}</b> abordajes en el escenario · ${I.gPerPassenger==null?'—':fmt(I.gPerPassenger)} g CO2e por abordaje`,co2:`<b>${fmt(I.co2AvoidedKg,1)} kg CO2e</b> evitados · ${fmt(I.co2LostKg,1)} kg en energía que se volvió calor`};
  return `<p class="reg279-lead">La Agenda 2030 no aparece en el material del curso ni en la presentación de 80 diapositivas. Donde sí se ve es en lo que el simulador mide: cuánta energía se recupera al frenar, cuánta se pierde en resistencias, cuántas personas se mueven y qué tan confiable es la operación. Esta pestaña lo relaciona con cuatro objetivos.</p>
  <div class="reg279-ods">${ODS279.map(o=>`<article class="o${o.ods}"><header><b>ODS ${o.ods}</b><span>${esc(o.name)}</span></header><small>${esc(o.meta)}</small><p class="reg279-kpi">${val[o.metric]}</p><ul>${o.where.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></article>`).join('')}</div>
  <h4>Energía de tracción desde que abriste el centro</h4><table class="reg279-table"><tr><th>Línea</th><th>Consumida (kWh)</th><th>Regenerada (kWh)</th><th>A resistencias (kWh)</th></tr>${rows}</table>
  <p class="reg279-hint">La Línea 8 tiene trenes NM-79 y MP-82 con chopper: su frenado es solo reostático, así que toda su energía de frenado se vuelve calor en el túnel. En la Línea 1 el NM-22 regenera cuando otro tren cercano está acelerando. ALAMYS reporta que el Metro no tiene almacenamiento de energía, así que lo que no toma otro tren se pierde.</p>
  <p class="reg279-hint">Emisiones con el factor de ${FESEN279.value} kg CO2e/kWh: <a href="${FESEN279.url}" target="_blank" rel="noopener">${esc(FESEN279.title)}</a>. El historial del Metro que aportaste menciona otro 2030: «${esc(STC2030.text)}»</p>`;}

 function render(force=false){const now=Date.now();if(!force&&(busy||now-lastRender<500))return;lastRender=now;q('[data-reg-clock]').textContent=`Hora del escenario ${clock279(engine)}`;
  const sel=tab==='regulacion'?{f:q('[data-reg-ltv-from]')?.value,t:q('[data-reg-ltv-to]')?.value,k:q('[data-reg-ltv-kmh]')?.value}:null;
  body.innerHTML=(flash?`<p class="reg279-flash" role="status">${esc(flash)}</p>`:'')+({trenes:trains,senales:signals,regulacion:regulation,alarmas:alarms,agenda}[tab])();
  if(sel){if(sel.f!=null)q('[data-reg-ltv-from]').value=sel.f;if(sel.t!=null)q('[data-reg-ltv-to]').value=sel.t;if(sel.k!=null)q('[data-reg-ltv-kmh]').value=sel.k;}}
 render(true);
 return{root,render,update(){render();},show(t){tab=t;for(const x of root.querySelectorAll('[data-reg-tab]'))x.setAttribute('aria-selected',String(x.dataset.regTab===tab));render(true);},dispose(){root.remove();}};
}
